/* empty css                                                                            */import{c as e,o as a,a1 as r}from"./chunks/framework.BRpGYp_P.js";const t=r('<h1 id="projektuppgift-rpg" tabindex="-1">Projektuppgift: RPG <a class="header-anchor" href="#projektuppgift-rpg" aria-label="Permalink to &quot;Projektuppgift: RPG&quot;">​</a></h1><h2 id="uppgiftsbeskrivning" tabindex="-1">Uppgiftsbeskrivning <a class="header-anchor" href="#uppgiftsbeskrivning" aria-label="Permalink to &quot;Uppgiftsbeskrivning&quot;">​</a></h2><p>Ni har i uppgift att göra en enklare interaktiv berättelse/spel. Berättelsen är textbaserad och ska innehålla val som användaren matar in så att den förgrenar sig. Er ambitionsnivå och tidsramen sätter gränser för hur omfattande detta blir.</p><h2 id="tidsplan" tabindex="-1">Tidsplan <a class="header-anchor" href="#tidsplan" aria-label="Permalink to &quot;Tidsplan&quot;">​</a></h2><ul><li>V45 måndag uppstart, planering, arbete</li><li>V46 måndag beskriv för mig handlingen/flödet, arbete (visa för mig om klar)</li><li>V47 måndag arbete klart (presentation)</li></ul><h2 id="bedomning" tabindex="-1">Bedömning <a class="header-anchor" href="#bedomning" aria-label="Permalink to &quot;Bedömning&quot;">​</a></h2><p>Ni kommer bli bedömda på hur ni hanterar de grundläggande programmeringstekniska verktygen (if, while, for samt datalagring i variabler) i en större öppen uppgift. Jag kommer även se hur komplext ert program är, se nedan.</p><h2 id="komplexitet" tabindex="-1">Komplexitet <a class="header-anchor" href="#komplexitet" aria-label="Permalink to &quot;Komplexitet&quot;">​</a></h2><p>För att öka på komplexiteten på uppgiften kan ni införa val i berättelsen som öppnar upp nya val på andra ställen (i tid eller rum), till exempel föremål som nycklar eller att man inhämtar information från personer eller iakttagelser. Jag kommer under projektets gång även visa exempel på hur man kan strukturera kod och göra textbaserade program lite mer roliga. Dessa teorier får ni gärna applicera på ert projekt.</p><h2 id="inlamning" tabindex="-1">Inlämning <a class="header-anchor" href="#inlamning" aria-label="Permalink to &quot;Inlämning&quot;">​</a></h2><p>Programmet lämnas in i Haldor senast måndag v47.</p>',11),n=[t],g=JSON.parse('{"title":"Projektuppgift: RPG","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"programming1/rpg/index.md","filePath":"programming1/rpg/index.md"}'),i={name:"programming1/rpg/index.md"},d=Object.assign(i,{setup(l){return(p,o)=>(a(),e("div",null,n))}});export{g as __pageData,d as default};
